import crypto from 'node:crypto';
const FUNNEL_HTML_BASE64 = '';
const BLOG_HTML_BASE64 = '';
import { validateAtm } from '../lib/atm-server.js';
import { supa } from '../lib/supabase-server.js';

function getBlogHtml(){ return Buffer.from(BLOG_HTML_BASE64,'base64').toString('utf8'); }
function pick(q,k,max=350){const v=q.get(k);return v?String(v).slice(0,max):''}
async function track(req,url,type,detail=''){
  try {
    const p=url.searchParams;
    const payload={
      session_id: crypto.randomUUID(), type, detail,
      utm_source:pick(p,'utm_source'), utm_medium:pick(p,'utm_medium'), utm_campaign:pick(p,'utm_campaign'), utm_content:pick(p,'utm_content'), utm_term:pick(p,'utm_term'),
      campaign_id:pick(p,'campaign_id'), adset_id:pick(p,'adset_id'), ad_id:pick(p,'ad_id'), placement:pick(p,'placement'),
      device:/Mobi|Android|iPhone/i.test(String(req.headers['user-agent']||''))?'mobile':'desktop',
      referrer:String(req.headers.referer||'').slice(0,700)
    };
    await supa('/rest/v1/events',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify(payload)});
  } catch(e) { console.error('atm tracking',e.message); }
}
export default async function handler(req,res){
  const proto=req.headers['x-forwarded-proto']||'https';
  const host=req.headers.host||'www.ohomeminseguro.store';
  const url=new URL(req.url,`${proto}://${host}`);
  const atm=url.searchParams.get('atm');
  try {
    const result=await validateAtm(atm);
    if(result.valid){
      track(req,url,'atm_valid',result.source).catch(()=>{});
      res.setHeader('Content-Type','text/html; charset=utf-8');
      res.setHeader('Cache-Control','private, no-store, max-age=0');
      res.setHeader('X-Robots-Tag','noindex, nofollow');
      return res.status(200).send(Buffer.from(FUNNEL_HTML_BASE64,'base64').toString('utf8'));
    }
    track(req,url,atm?'atm_invalid':'atm_missing').catch(()=>{});
    res.setHeader('Content-Type','text/html; charset=utf-8');
    res.setHeader('Cache-Control','public, max-age=0, s-maxage=120');
    return res.status(200).send(getBlogHtml());
  } catch(e){
    console.error(e);
    res.setHeader('Content-Type','text/html; charset=utf-8');
    res.setHeader('Cache-Control','public, max-age=0, s-maxage=120');
    return res.status(200).send(getBlogHtml());
  }
}
